// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Waves".

I actually created this shader on the theme of "Retro Waves"
because I had already started working on it shortly before the
last challenge stream. Since it wasn't clear at that point
which of the two suggested themes would prevail, but it was
clear that it would be one of them, I decided to combine both.
I have therefore chosen a retrowave style for the shader.

2025-07-21 Update: use p5.js version 1.7 or higher to access the new WebGL 2 support.
*/

const scale = Math.max(1, devicePixelRatio)
let theShader;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2685074/files/vert.glsl', 'frag.glsl');
}

function setup() {
	pixelDensity(scale)
  createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
  resizeCanvas(windowWidth, windowHeight)
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width * scale, height * scale]);
  theShader.setUniform("time", millis() / 1000.0);
  rect(0, 0, width, height);
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1.,1); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define T mod(time,SECS)
#define S smoothstep
#define SE(v,a) S(a+3./MN,a-3./MN,v)
#define MN min(R.x,R.y)
#define SECS 60.
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1.;
	for (int i; i++<5;) {
		t+=a*noise(p);
		p*=2.;
		a/=2.;
	}
	return t;
}
float birds(vec2 uv, float s) {
	// get the id of each column of the following grid
	float n=3., id=floor(uv.x/n+.5);
	// define a grid with three columns
	uv.x-=clamp(round(uv.x/n),-1.,1.)*n;
	// let them fly in formation
	uv.y-=id;
	// a bird is symmetrical along the x-axis
	uv.x=abs(uv.x);
	// limit the extent of the wings
	if (uv.x>1.) return 1.;
	// animate the wings by a sine
	float f=sin(T*7.*s+id*.3), e=f*f*2.+1.,
	// shape the wings
	d=abs(uv.y*e-sqrt(uv.x));
	// draw them as lines
	return SE(.15,d);
}
// Returns the pattern of the moon's atmosphere for a given point and an animation time
vec3 moonPattern(vec2 uv, float anim) {
	// animate the moon setting
	uv.y+=anim;
	// return a cloud pattern slightly rotated.
	return vec3(fbm(uv+.4*noise(uv.yy*15.-uv.xx*8.+vec2(-.9,-1.6))));
}
// Defines the entry function of the shader
void main() {
	// calculate the unit vector
	vec2 uv=(FC-.5*R)/MN;
	// initialize the animation time
	float anim=pow(S(.0,1.,fract(T/SECS)),SECS);
	// initialize the color vector
	vec3 col=vec3(0);
	// paint everything above the water level
	if (uv.y>-.2) {
		float
		moon=SE(length(uv+vec2(0,anim)),.4),
		front=SE(uv.y+.1,.2*noise(uv.xx*12.-noise(uv.yx*4.))),
		back=SE(uv.y+.05,.2*noise(uv.xx*4.)),
		bf=back-front,
		monts=max(front,back),
		sky=fbm((uv+vec2(0,4))*3.+noise(uv.yx*10.-uv.xx*4.));
		vec3
		f=mix(hue(.95-uv.y*3.5),vec3(bf),12.*uv.y)*bf,
		b=vec3(bf);
		b=mix(hue(.95+uv.y*.2),vec3(front),10.*uv.y+.35)*front;
		moon-=monts;
		float s=sky;
		sky=S(.5,.0,max(max(moon,monts),-sky));
		col=max(f,b);
		col=max(col,mix(
			1.5*S(.0,1.125,moonPattern(uv,anim)*moon*vec3(2,.4,.6)),
			vec3(moon),
			S(.0,1.,min(.1,uv.y))*.5)
		);
		col+=s*sky*vec3(noise(uv.xx+1.))*dot(vec3(.21,.71,.07),hue(S(-2.,12.,uv.x)+.5))*vec3(2,.1,.9);
		// add the bird animation
		float tt=(SECS-3.)*.1, t=min(T*.1+.1,tt);
		col+=t<tt?mix(
			1.-birds((uv-vec2(S(.0,1.,t/tt),S(.1,2.2,sin(t/tt))))*rot(max(.3,sin(t)))*(28.+120.*S(.1,1.5,t*1.5)),.5),
			.0,
			// fade out into the sunset
			pow(S(.9,1.,t/tt),12.)
		):.0;
	} else {
		// paint the water with gradient, highlights and wave animation
		col=hue(-1.5*max(1.-anim,.85)-max(-1.,uv.y))+1.-(fbm(uv*4.+noise(uv.xx*2.-uv.yy*100.-vec2(T*.5,T*.2))));
	}
	// vignette (dimensions of the window, normalized)
	uv=2.*(FC/R)-1.;
	// widen the frame
	uv*=.92;
	// increase the curvature in the corners
	uv*=uv*uv;
	// calculate the distance to the vignette and soften the transition
	float v=pow(dot(uv,uv),.8);
	// darken the corners (yes absolute black leads to the desired result)
	col=mix(col,vec3(0),v);
	// fade in
	float t=min(T*.3,1.);
	col=mix(vec3(0),max(col,.08),t*t);
	// fade out
	col=mix(col,vec3(0),sqrt(anim+.05));
	// color grade
	col=tanh(S(.0,1.,col));
	col=sqrt(col)+.5*sqrt(col);
	// output the pixel's color
	O=vec4(col,1);
}

